/* FFmpeg finishing pass for the HyperFrames render.
 *
 *   node video/post/post.mjs [--bgm path/to/track.mp3] [--no-subs]
 *
 * - burns the Korean subtitles (subs.ass, generated by video/hf/build.mjs) with libass + Pretendard
 * - light grade (contrast / saturation), no LUT
 * - music bed: a royalty-free track you pass with --bgm (e.g. from the YouTube Audio Library, attribution-free),
 *   otherwise a soft synthesized pad; ducked under the narration with a sidechain compressor
 * - loudness normalised to -16 LUFS / -1.5 dBTP (EBU R128 two-pass would be stricter; one pass is enough here)
 */
import { execFileSync } from "node:child_process";
import { copyFileSync, existsSync, mkdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const POST = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(POST, "../..");
const IN = resolve(POST, "../hf/renders/base.mp4");
const OUTDIR = resolve(POST, "../out");
const OUT = join(OUTDIR, "GeoBuild_Impact_3D_JIRISO_DATA_STUDIO.mp4");
const args = process.argv.slice(2);
const bgmArg = args.includes("--bgm") ? resolve(args[args.indexOf("--bgm") + 1]) : null;
const subs = !args.includes("--no-subs");
const { total } = JSON.parse(readFileSync(join(POST, "timeline.json"), "utf8"));
mkdirSync(OUTDIR, { recursive: true });
mkdirSync(join(POST, "fonts"), { recursive: true });
const font = join(ROOT, "frontend/node_modules/pretendard/dist/public/static/Pretendard-SemiBold.otf");
if (!existsSync(join(POST, "fonts/Pretendard-SemiBold.otf"))) copyFileSync(font, join(POST, "fonts/Pretendard-SemiBold.otf"));
const ff = (a) => execFileSync("ffmpeg", ["-y", "-hide_banner", "-loglevel", "error", ...a], { cwd: POST, stdio: "inherit" });

/* 1. music bed */
let bgm = bgmArg;
if (!bgm) {
  // Two interleaved layers of slow chord swells (each fades to zero exactly where its chord changes -> no clicks).
  // Cmaj9 - Am9 - Fmaj7(#11) - G6/9, voiced low and soft.
  const chords = [[130.81, 196.0, 246.94, 293.66], [110.0, 164.81, 246.94, 261.63], [87.31, 174.61, 220.0, 329.63], [98.0, 146.83, 220.0, 293.66]];
  const pick = (k, n) => `if(eq(${n},0),${chords[0][k]},if(eq(${n},1),${chords[1][k]},if(eq(${n},2),${chords[2][k]},${chords[3][k]})))`;
  const layer = (off) => {
    const n = `floor(mod(t+${off},32)/8)`, env = `pow(sin(PI*mod(t+${off},8)/8),1.6)`;
    return `${env}*(${[0, 1, 2, 3].map((k) => `${k === 0 ? 0.9 : 0.55}*sin(2*PI*${pick(k, n)}*t)`).join("+")})`;
  };
  const expr = `0.07*(${layer(0)}+${layer(4)})`;
  ff(["-f", "lavfi", "-i", `aevalsrc=exprs='${expr}':s=48000:d=${Math.ceil(total) + 2}`, "-af",
    "lowpass=f=1800,aecho=0.8:0.85:120|240:0.35|0.22,afade=t=in:d=2.5,volume=1.0", "-ac", "2", "-c:a", "pcm_s16le", "bgm_pad.wav"]);
  bgm = join(POST, "bgm_pad.wav");
}

/* 2. mix: voice (from the render) + ducked music, then loudness */
const fadeOut = Math.max(0, total - 3.5).toFixed(2);
ff(["-i", IN, "-stream_loop", "-1", "-i", bgm, "-filter_complex",
  [
    `[0:a]aformat=sample_rates=48000:channel_layouts=stereo,asplit=2[vo][key]`,
    `[1:a]aformat=sample_rates=48000:channel_layouts=stereo,atrim=0:${total.toFixed(2)},${bgmArg ? "acompressor=threshold=0.1:ratio=3:attack=20:release=400,volume=0.42" : "volume=0.55"},afade=t=out:st=${fadeOut}:d=3.5[m]`,
    `[m][key]sidechaincompress=threshold=0.03:ratio=8:attack=40:release=600:makeup=1[duck]`,
    `[vo][duck]amix=inputs=2:normalize=0:duration=first,loudnorm=I=-16:TP=-1.5:LRA=9[a]`,
  ].join(";"),
  "-map", "[a]", "-c:a", "pcm_s16le", "-ar", "48000", "mix.wav"]);

/* 3. picture: grade + subtitles, mux */
const vf = ["eq=contrast=1.03:saturation=1.06:gamma=0.99", subs ? "ass=subs.ass:fontsdir=fonts" : null].filter(Boolean).join(",");
ff(["-i", IN, "-i", "mix.wav", "-map", "0:v", "-map", "1:a", "-vf", vf, "-c:v", "libx264", "-preset", "slow", "-crf", "17", "-pix_fmt", "yuv420p",
  "-c:a", "aac", "-b:a", "192k", "-movflags", "+faststart", "-shortest", OUT]);
console.log("wrote", OUT);
